var distMoney = function(money, children) {
    if (money < children) return -1;
    money -= children;
    const k = Math.floor(money / 7);
    if (k > children) return children - 1;
    if (k === children) return (money % 7 === 0) ? children : children - 1;
    if (k === children - 1 && money % 7 === 3) return k - 1;
    return k;
};
